const body = $json.body ?? $json;

const errors = [];

const source = String(body.source ?? '').trim().toLowerCase();
const allowedSources = [
  'demo_request',
  'website',
  'partner_referral',
  'outbound'
];

const intakeId = String(body.intake_id ?? '').trim();
const externalLeadId = String(body.external_lead_id ?? '').trim();
const firstName = String(body.first_name ?? '').trim();
const lastName = String(body.last_name ?? '').trim();
const email = String(body.email ?? '').trim().toLowerCase();
const companyName = String(body.company_name ?? '').trim();
const country = String(body.country ?? '').trim();

const employeeCount =
  body.employee_count === null ||
  body.employee_count === undefined ||
  body.employee_count === ''
    ? null
    : Number(body.employee_count);

if (!intakeId) errors.push('intake_id is required');
if (!externalLeadId) errors.push('external_lead_id is required');

if (!allowedSources.includes(source)) {
  errors.push('source is invalid');
}

if (!lastName) errors.push('last_name is required');
if (!email) errors.push('email is required');
if (!companyName) errors.push('company_name is required');

if (
  employeeCount !== null &&
  (!Number.isInteger(employeeCount) || employeeCount < 0)
) {
  errors.push('employee_count must be a non-negative integer');
}

return {
  json: {
    validation_status: errors.length === 0 ? 'valid' : 'invalid',
    validation_errors: errors,

    intake_id: intakeId,
    external_lead_id: externalLeadId,
    source,
    first_name: firstName || null,
    last_name: lastName,
    email,
    company_name: companyName,
    country: country || null,
    employee_count: employeeCount,

    raw_payload: body,
    received_at: new Date().toISOString()
  }
};

const lead = $json;

const missingFields = [];

if (!lead.email) missingFields.push('email');
if (!lead.company_name) missingFields.push('company_name');
if (!lead.country) missingFields.push('country');
if (!lead.source) missingFields.push('source');

let dataReadiness = 'Ready';
let readinessReason = 'Required lead data is available';

if (missingFields.length > 0) {
  dataReadiness = 'Incomplete';
  readinessReason = `Missing required fields: ${missingFields.join(', ')}`;
}

return {
  json: {
    ...lead,
    data_readiness: dataReadiness,
    data_readiness_reason: readinessReason,
    missing_fields: missingFields
  }
};

const lead = $json;

const country = String(lead.country ?? '').trim();
const source = String(lead.source ?? '').trim();
const employeeCount = lead.employee_count;

const supportedCountries = [
  'United States',
  'Canada',
  'Germany',
  'United Kingdom',
  'France',
  'Netherlands',
  'Spain',
  'Italy'
];

let icpFit = 'Weak Fit';
let icpReason = 'Lead does not match the current ICP rules';

if (
  supportedCountries.includes(country) &&
  employeeCount >= 50 &&
  employeeCount <= 999
) {
  icpFit = 'Strong Fit';
  icpReason = 'Supported geography and target company size';
} else if (
  supportedCountries.includes(country) &&
  (
    (employeeCount >= 20 && employeeCount <= 49) ||
    employeeCount >= 1000
  )
) {
  icpFit = 'Moderate Fit';
  icpReason = 'Supported geography with non-core company size';
}

let buyingIntent = 'Low Intent';
let intentReason = 'No strong buying signal detected';

if (source === 'demo_request') {
  buyingIntent = 'High Intent';
  intentReason = 'Demo request indicates explicit buying interest';
} else if (source === 'partner_referral') {
  buyingIntent = 'Medium Intent';
  intentReason = 'Partner referral indicates meaningful interest';
} else if (source === 'website') {
  buyingIntent = 'Medium Intent';
  intentReason = 'Website lead shows inbound interest';
} else if (source === 'outbound') {
  buyingIntent = 'Low Intent';
  intentReason = 'Outbound source has no explicit inbound buying signal';
}

return {
  json: {
    ...lead,
    icp_fit: icpFit,
    icp_reason: icpReason,
    buying_intent: buyingIntent,
    buying_intent_reason: intentReason
  }
};

const lead = $json;

let qualificationState = 'Needs Review';
let qualificationReason = 'Lead requires manual review';

if (lead.icp_fit === 'Strong Fit' && lead.buying_intent === 'High Intent') {
  qualificationState = 'Qualified';
  qualificationReason = 'Strong ICP fit with high buying intent';
} else if (
  (lead.icp_fit === 'Strong Fit' || lead.icp_fit === 'Moderate Fit') &&
  (lead.buying_intent === 'Low Intent' || lead.buying_intent === 'Medium Intent')
) {
  qualificationState = 'Nurture';
  qualificationReason = 'Plausible ICP fit but buying intent is below qualification threshold';
} else if (lead.icp_fit === 'Weak Fit') {
  qualificationState = 'Disqualified';
  qualificationReason = 'Lead does not meet current ICP criteria';
}

return {
  json: {
    ...lead,
    qualification_state: qualificationState,
    qualification_reason: qualificationReason
  }
};

const lead = $json;

const country = String(lead.country ?? '').trim();
const employeeCount = lead.employee_count;
const source = String(lead.source ?? '').trim();

const naCountries = [
  'United States',
  'Canada'
];

const emeaCountries = [
  'Germany',
  'United Kingdom',
  'France',
  'Netherlands',
  'Spain',
  'Italy'
];

let routingTarget = 'Manual Review';
let routingReason = 'No deterministic routing rule matched';

if (employeeCount >= 1000) {
  routingTarget = 'Enterprise Review';
  routingReason = 'Enterprise-size company requires enterprise review';
} else if (source === 'partner_referral') {
  routingTarget = 'Partner Motion';
  routingReason = 'Partner referral takes routing precedence';
} else if (naCountries.includes(country)) {
  if (employeeCount >= 20 && employeeCount <= 99) {
    routingTarget = 'NA SMB';
    routingReason = 'North America SMB routing rule matched';
  } else if (employeeCount >= 100 && employeeCount <= 999) {
    routingTarget = 'NA Mid-Market';
    routingReason = 'North America mid-market routing rule matched';
  }
} else if (emeaCountries.includes(country)) {
  if (employeeCount >= 20 && employeeCount <= 99) {
    routingTarget = 'EMEA SMB';
    routingReason = 'EMEA SMB routing rule matched';
  } else if (employeeCount >= 100 && employeeCount <= 999) {
    routingTarget = 'EMEA Mid-Market';
    routingReason = 'EMEA mid-market routing rule matched';
  }
}

return {
  json: {
    ...lead,
    routing_target: routingTarget,
    routing_reason: routingReason
  }
};

const lead = $json;

const now = new Date();

let slaHours = 24;
let slaType = 'Other Qualified Lead';

if (lead.source === 'demo_request') {
  slaHours = 2;
  slaType = 'High-Intent Demo Request';
} else if (lead.source === 'partner_referral') {
  slaHours = 4;
  slaType = 'Partner Referral';
}

const slaDueAt = new Date(
  now.getTime() + slaHours * 60 * 60 * 1000
);

return {
  json: {
    ...lead,
    sla_status: 'Active',
    sla_type: slaType,
    sla_started_at: now.toISOString(),
    sla_due_at: slaDueAt.toISOString()
  }
};

